Given a string s consisting of only lowercase alphabet characters, count all pairs of substrings of s that are anagrams of each other. Examples:Input: s = "xyyx"Output: 4Explanation: Total anagrammatic substring pairs are: ["x", "x"], ["y", "y"], ["xy", "yx"], ["xyy", "yyx"]Input: s = "geeg"Output: 4Explanation: Valid anagrammatic substring pairs are: ["g", "g"], ["e", "e"], ["gee", "eeg"], ["ge", "eg"]Input: s = "aba"Output: 2Explanation: Anagrammatic substring pairs include: ["a", "a"], ["ab", "ba"]Table of Content[Naive Approach] Generate all substrings and Compare - O(n^5 log n) Time and O(n^3) Space [Expected Approach 1] Sorted Substring Hashing - O(n^3 log n) Time and O(n^3) Space[Expected Approach 2] Using Hash Map - O(n^2) Time and O(n^2) Space[Naive Approach] Generate all substrings and Compare - O(n^5 log n) Time and O(n^3) Space Generate all possible substrings of the given string and store them. Then compare every pair of substrings and check whether they are anagrams by sorting both strings. If two sorted substrings are equal, increment the count of anagrammatic pairs.
            C++

    #include <iostream>
using namespace std;

bool isAnagram(string a, string b) {
    if (a.length() != b.length())
        return false;

    sort(a.begin(), a.end());
    sort(b.begin(), b.end());

    return a == b;
}

int countAnagramPairs(string s) {
    int n = s.length();
    vector<string> substrings;

    // Step 1: Generate all substrings
    for (int i = 0; i < n; i++) {
        for (int len = 1; len <= n - i; len++) {
            substrings.push_back(s.substr(i, len));
        }
    }

    int count = 0;

    // Step 2: Compare every pair of substrings
    for (int i = 0; i < substrings.size(); i++) {
        for (int j = i + 1; j < substrings.size(); j++) {
            if (isAnagram(substrings[i], substrings[j])) {
                count++;
            }
        }
    }

    return count;
}

int main() {
    string s = "abba";
    cout << countAnagramPairs(s);
    return 0;
}


